import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    # walls: contiguous straight segments of non-bg colors; markers: isolated non-bg cells
    seen=set(); segs=[]; marks=[]
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v==bg: continue
            nb=(r,c) in seen
            for dr,dc in [(0,1),(1,0),(0,-1),(-1,0)]:
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W and g[nr][nc]==v:
                    seen.add((r,c))
                    segs.append([(r,c),(nr,nc)])
    # markers: non-bg cells not part of any seg (length>=2 straight)
    used=set(segs[0][0])|set(segs[0][1])
    for (r,c) in [(i,j) for i in range(H) for j in range(W) if g[i][j]!=bg]:
        if (r,c) not in used:
            marks.append((r,c,g[r][c]))
    out=[row[:] for row in g]
    def man(a,b): return abs(a[0]-b[0])+abs(a[1]-b[1])
    for (mr,mc,mv) in marks:
        best=None
        for s in segs:
            for p in s:
                d=man([(mr,mc)],p)
                if best is None or d<best[0]: best=(d,p,s)
        d,p,ws=best
        # direction toward wall: choose axis with smaller offset
        if p[0]!=mr and p[1]!=mc:
            dr,d_=abs(p[0]-mr),abs(p[1]-mc)
            ax='r' if dr<=d_ else 'c'
        elif p[0]!=mr: ax='r'; step=p[0]>mr- (0) and 1 or -1
        else: ax='c'; step=1 if p[1]>mc else -1
        # determine fill: walk from marker toward wall until adjacent or edge
        rr,cc=mr,mc
        while True:
            nr,nc=rr+step*(1 if ax=='r' else 0), cc+step*(1 if ax=='c' else 0)
            if not(0<=nr<H and 0<=nc<W): break
            if (nr,nc) in [q for q in ws]: break
            out[nr][nc]=mv
            rr,cc=nr,nc
        out[mr][mc]=4
    return out

