def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    def segs_of():
        s=[]; used=set()
        for r in range(H):
            for c in range(W):
                if g[r][c]!=bg and (r,c) not in used:
                    stack=[(r,c)]; comp=[]
                    while stack:
                        a,b=stack.pop()
                        if (a,b) in used: continue
                        used.add((a,b))
                        comp.append((a,b))
                        for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                            na,nb=a+dr,b+dc
                            if 0<=na<H and 0<=nb<W and g[na][nb]==g[a][b] and (na,nb) not in used:
                                stack.append((na,nb))
                    # check straight
                    if len(comp)>=2:
                        rs={x for x,y in comp}; cs={y for x,y in comp}
                        if len(rs)==1 or len(cs)==1: s.append((comp[0],comp[-1]))
        return s
    ws=segs_of()
    used=set()
    for a,b in ws: used.update(a); used.update(b)
    marks=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=bg and (r,c) not in used]
    out=[row[:] for row in g]
    def man(a,b): return abs(a[0]-b[0])+abs(a[1]-b[1])
    for mr,mc,mv in marks:
        d,wall=None,None
        for a,b in ws:
            for p in [a,b]:
                dd=man((mr,mc),p)
                if wall is None or dd<d: d=dd; wall=p; ws_seg=(a,b)
        ax='r' if abs(mr-wall[0])<=abs(mc-wall[1]) else 'c'
        step = 1 if wall[0]>mr else -1 if ax=='r' else (1 if wall[1]>mc else -1)
        rr,cc=mr,mc
        while True:
            nr,nc=rr+step*(1 if ax=='r' else 0), cc+step*(1 if ax=='c' else 0)
            if not(0<=nr<H and 0<=nc<W) or (nr,nc) in ws_seg: break
            out[nr][nc]=mv
            rr,cc=nr,nc
        out[mr][mc]=4
    return out

