from collections import deque, Counter

def solve(gi):
    h,w=len(gi),len(gi[0])
    cnt=Counter(x for r in gi for x in r)
    bg=cnt.most_common(1)[0][0]
    out=[r[:] for r in gi]
    # components of non-bg (4-conn)
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if gi[r][c]!=bg and (r,c) not in seen:
                q=deque([(r,c)]); comp=[]; seen.add((r,c))
