    h,w=len(gi),len(gi[0])
    cnt=Counter(v for r in gi for v in r)
    bgv=cnt.most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if gi[r][c]!=bgv and (r,c) not in seen:
                q=deque([(r,c)]); comp=[]; seen.add((r,c))
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and gi[na][nb]!=bgv and (na,nb) not in seen:
                            seen.add((na,nb)); q.append((na,nb))
                comps.append(comp)
    walls=[]; marks=[]
    for comp in comps:
        if len(comp)>=2: walls.append({'cells':comp})
        else: marks.append(comp[0])
    out=[r[:] for r in gi]
    raycol={m:gi[m[0]][m[1]] for m in marks}
    def horiz(cs): return min(x[1] for x in cs)==max(x[1] for x in cs)
    def info(cs):
        if horiz(cs):
            row=cs[0][0]; ck=sorted(x[1] for x in cs)
            return {'row':row,'c0':ck[0],'L':len(ck),'offs':lambda c:c-ck[0]}
        else:
            col_=cs[0][1]; rs_=sorted(x[0] for x in cs)
            return {'col':col_,'r0':rs_[0],'L':len(rs_),'offs':lambda r:r-rs_[0]}

    for m in marks:
        mr,mc=m
        best=None
        for i,ww in enumerate(walls):
            for a,b in ww['cells']:
                dd=abs(mr-a)+abs(mc-b)
                if best is None or dd<best[0]:
                    best=(dd,i,a,b)
        d_,iw,aa,bb=best
        wi=info(walls[iw]['cells'])
        ih = horiz(walls[iw]['cells'])
        if ih:   # target wall horizontal: beam vertical from marker toward it
            step = 1 if mr<wi['row'] else -1
            nr,nc=mr+step, mc
            while 0<=nr<h and 0<=nc<w:
                if out[nr][nc]==bgv:
                    out[nr][nc]=raycol[m]; nr+=step
                elif gi[nr][nc]!=bgv: break
                else: break
            impact = mc - wi['c0']
            rays = sorted([impact, wi['L']-1-impact])
            s=wi['r0']; sp = 1 if mr>s else -1
            for p in rays:
                r_=s+p
                while 0<=r_<h and 0<=mc<w:
                    if out[r_][mc]==bgv: out[r_][mc]=raycol[m]
                    r_+=sp
        else:    # target wall vertical: beam horizontal toward it
            step = 1 if mc>wi['col'] else -1
            nr,nc=mr, mc+step
            while 0<=nr<h and 0<=nc<w:
                if out[nr][nc]==bgv:
                    out[nr][nc]=raycol[m]; nc+=step
                elif gi[nr][nc]!=bgv: break
                else: break
            impact = mr - wi['r0']
            rays = sorted([impact, wi['L']-1-impact])
            s=wi['c0']; sp = 1 if mc>s else -1
            for p in rays:
                c_=s+p
                rr_=mr
                while 0<=rr_<h and 0<=c_<w:
                    if out[rr_][c_]==bgv: out[rr_][c_]=raycol[m]
                    rr_+=1
    for m in marks:
        out[m[0]][m[1]]=4
    return out

