import itertools

def parse(gi):
    h,w=len(gi),len(gi[0])
    cnt=Counter(v for r in gi for v in r)
    bgv=cnt.most_common(1)[0][0]
    comps=[]; seen=set()
    for r in range(h):
        for c in range(w):
            if gi[r][c]!=bgv and (r,c) not in seen:
                q=deque([(r,c)]); comp=[]; seen.add((r,c))
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and gi[na][nb]!=bgv and (na,nb) not in seen:
                            seen.add((na,nb)); q.append((na,nb))
                comps.append(comp)
    walls=[comp for comp in comps if len(comp)>=2]
    marks=[comp[0] for comp in comps if len(comp)==1]
    return bgv,walls,marks

def info(cs):
    if min(x[1] for x in cs)==max(x[1] for x in cs):
        row=cs[0][0]; ck=sorted(x[1] for x in cs)
        return {'type':'h','row':row,'start':ck[0],'L':len(ck),'offs':lambda c:c-ck[0]}
    else:
        col_=cs[0][1]; rs=sorted(x[0] for x in cs)
        return {'type':'v','col':col_,'start':rs[0],'L':len(rs),'offs':lambda r:r-rs[0]}

def solve(gi, params):
    h,w=len(gi),len(gi[0])
    bgv,walls,marks=parse(gi)
    out=[r[:] for r in gi]
    def draw(cells,color):
        for (r_,c_) in cells:
            if 0<=r_<h and 0<=c_<w and out[r_][c_]==bgv: out[r_][c_]=color
    for m in marks:
        mr,mc=m
        # beam toward nearest wall cell (Manhattan)
        best=None
        for i,ww in enumerate(walls):
            for a,b in ww:
                dd=abs(mr-a)+abs(mc-b)
                if best is None or dd<best[0]: best=(dd,i,a,b)
        _,iw,t,a,b=best
        wi=info(walls[iw])
        # beam step direction
        if wi['type']=='v':  # target vertical: beam horizontal
            st=1 if mc<wi['col'] else -1
            nr,nc=mr,mc+st
            while 0<=nr<h and 0<=nc<w and out[nr][nc]==bgv:
                out[nr][nc]=params['C']; nc+=st
            impact = mr-wi['start']
            offs = sorted({impact, wi['L']-1-impact})
            # firing wall: the other parallel wall
            fw=[x for x in walls if x is not walls[iw]]
            assert len(fw)==1
            fw=fw[0]; wfi=info(fw)
            fs=wfi['start']
            sp=1 if mc>fs else -1
            for p in offs:
                c_=fs+p
                r_=mr
                while 0<=r_<h and 0<=c_<w and out[r_][c_]==bgv:
                    out[r_][c_]=params['C']; r_+=1
        else:                 # target horizontal: beam vertical
            st=1 if mr<wi['row'] else -1
            nr,nc=mr+st,mc
            while 0<=nr<h and 0<=nc<w and out[nr][nc]==bgv:
                out[nr][nc]=params['C']; nr+=st
            impact = mc-wi['start']
            offs = sorted({impact, wi['L']-1-impact})
            fw=[x for x in walls if x is not walls[iw]]
            assert len(fw)==1
            fw=fw[0]; wfi=info(fw)
            fs=wfi['start']
            sp=1 if mr>fs else -1
            for p in offs:
                r_=fs+p
                c_=mc
                while 0<=r_<h and 0<=c_<w and out[r_][c_]==bgv:
                    out[r_][c_]=params['C']; r_+=sp
    for m in marks:
        out[m[0]][m[1]]=params.get('M4',4)
    return out

